PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS players(player_id TEXT PRIMARY KEY,life_id TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS wallet_bindings(wallet_address TEXT NOT NULL,chain_id INTEGER NOT NULL,player_id TEXT NOT NULL REFERENCES players(player_id),verified_at INTEGER NOT NULL,PRIMARY KEY(wallet_address,chain_id));
CREATE TABLE IF NOT EXISTS player_state(player_id TEXT PRIMARY KEY REFERENCES players(player_id),revision INTEGER NOT NULL CHECK(revision>=1),updated_at INTEGER NOT NULL,schema_version INTEGER NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS state_revisions(player_id TEXT NOT NULL REFERENCES players(player_id),revision INTEGER NOT NULL,payload TEXT NOT NULL,updated_at INTEGER NOT NULL,schema_version INTEGER NOT NULL,PRIMARY KEY(player_id,revision));
CREATE TABLE IF NOT EXISTS snapshots(snapshot_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players(player_id),schema_version INTEGER NOT NULL,created_at INTEGER NOT NULL,source_revision INTEGER NOT NULL,content_hash TEXT NOT NULL,reason TEXT NOT NULL,payload_reference TEXT NOT NULL UNIQUE);
CREATE INDEX IF NOT EXISTS snapshots_owner ON snapshots(player_id,created_at DESC);
CREATE TABLE IF NOT EXISTS recovery_receipts(recovery_receipt_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players(player_id),from_revision INTEGER NOT NULL,to_snapshot_id TEXT NOT NULL REFERENCES snapshots(snapshot_id),new_revision INTEGER NOT NULL,timestamp INTEGER NOT NULL,result TEXT NOT NULL,UNIQUE(player_id,new_revision));
CREATE TABLE IF NOT EXISTS game_receipts(receipt_id TEXT NOT NULL,player_id TEXT NOT NULL REFERENCES players(player_id),payload TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(player_id,receipt_id));
CREATE TABLE IF NOT EXISTS logistics_projections(mission_id TEXT NOT NULL,player_id TEXT NOT NULL REFERENCES players(player_id),revision INTEGER NOT NULL,updated_at INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(player_id,mission_id));
CREATE TABLE IF NOT EXISTS auth_challenges(challenge_id TEXT PRIMARY KEY,player_id TEXT NOT NULL,wallet_address TEXT NOT NULL,chain_id INTEGER NOT NULL,domain TEXT NOT NULL,nonce TEXT NOT NULL UNIQUE,issued_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,message TEXT NOT NULL,consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,challenge_id TEXT NOT NULL UNIQUE REFERENCES auth_challenges(challenge_id),player_id TEXT NOT NULL REFERENCES players(player_id),expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency(scope TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,response TEXT NOT NULL,status INTEGER NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(scope,key));
CREATE TABLE IF NOT EXISTS conflicts(conflict_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players(player_id),base_revision INTEGER NOT NULL,current_revision INTEGER NOT NULL,current_payload TEXT NOT NULL,candidate_payload TEXT NOT NULL,created_at INTEGER NOT NULL,resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS recovery_previews(preview_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players(player_id),snapshot_id TEXT NOT NULL REFERENCES snapshots(snapshot_id),expected_revision INTEGER NOT NULL,candidate_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS staging_operations(operation_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players(player_id),payload_reference TEXT NOT NULL,content_hash TEXT NOT NULL,phase TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mutation_guards(guard_id TEXT PRIMARY KEY,player_id TEXT NOT NULL,expected_revision INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS revision_guard BEFORE INSERT ON mutation_guards BEGIN SELECT CASE WHEN COALESCE((SELECT revision FROM player_state WHERE player_id=NEW.player_id),0)!=NEW.expected_revision THEN RAISE(ABORT,'REVISION_CONFLICT') END; END;
CREATE TABLE IF NOT EXISTS challenge_guards(guard_id TEXT PRIMARY KEY,challenge_id TEXT NOT NULL,now INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS challenge_guard BEFORE INSERT ON challenge_guards BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM auth_challenges WHERE challenge_id=NEW.challenge_id AND consumed=0 AND expires_at>NEW.now) THEN RAISE(ABORT,'CHALLENGE_REPLAY_OR_EXPIRED') END; END;
CREATE TABLE IF NOT EXISTS preview_guards(guard_id TEXT PRIMARY KEY,preview_id TEXT NOT NULL,now INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS preview_guard BEFORE INSERT ON preview_guards BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM recovery_previews WHERE preview_id=NEW.preview_id AND consumed=0 AND expires_at>NEW.now) THEN RAISE(ABORT,'RESTORE_REPLAY_OR_EXPIRED') END; END;
CREATE TRIGGER IF NOT EXISTS session_binding_guard BEFORE INSERT ON sessions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM auth_challenges c JOIN wallet_bindings b ON b.wallet_address=c.wallet_address AND b.chain_id=c.chain_id WHERE c.challenge_id=NEW.challenge_id AND b.player_id=NEW.player_id AND c.player_id=NEW.player_id) THEN RAISE(ABORT,'WALLET_BINDING_CONFLICT') END; END;
CREATE TRIGGER IF NOT EXISTS game_receipt_immutable BEFORE INSERT ON game_receipts BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM game_receipts WHERE player_id=NEW.player_id AND receipt_id=NEW.receipt_id AND payload!=NEW.payload) THEN RAISE(ABORT,'GAME_RECEIPT_MISMATCH') END; END;
